window.kbPageData["views/entry/k-f21d7fa71f536ad2"] = {"key":"entry/k-f21d7fa71f536ad2","state":{"route":"entry/k-f21d7fa71f536ad2"},"node":{"id":"k-f21d7fa71f536ad2","mode":"k","title":"稳中求进工作总基调","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["稳中求进工作总基调","数字贸易改革创新的总基调"],"qs":["政治理论必刷100题#48","政治理论必刷100题#89"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["modern"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论"],"来源主题":["经济指标与宏观调控"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"稳中求进是指在保持总体稳定的基础上积极推进发展和改革的工作总基调。","review":{"title":"稳中求进工作总基调","type":"制度与规则","definition":"稳中求进是指在保持总体稳定的基础上积极推进发展和改革的工作总基调。","explanation":"2024年中共中央办公厅、国务院办公厅《关于数字贸易改革创新发展的意见》在总体要求中明确坚持稳中求进，并提出促进实体经济和数字经济深度融合。2024年12月2日第四次“一带一路”建设工作座谈会讲话也明确坚持稳中求进工作总基调，并提出以互联互通为主线。","basis":"据关联原题及所列出处编释。","references":[{"source":"trade","location":"一、总体要求"}],"examFocus":{"政治理论必刷100题#48":"对照数字贸易改革创新发展的政策文件，区分工作总基调、基本原则和实施举措。","政治理论必刷100题#89":"核对第四次“一带一路”建设工作座谈会讲话中工作总基调的完整表述，并区分原则、主线和协调机制。"}},"aspects":[{"title":"数字贸易改革创新的总体要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题选C。①把稳中求进和促进实体经济与数字经济深度融合列入数字贸易改革创新发展的总体要求，③培育经营主体、④发挥引导基金作用也符合《意见》。②颠倒了政策原则的用词，文件表述是“创新为要、安全为基”。","evidence":"坚持稳中求进工作总基调","qids":["政治理论必刷100题#48"]}]},{"title":"共建“一带一路”的工作总基调","uses":[{"unit":"Q2","role":"直接考查","use":"本题为选非题，选D。按2024年12月2日第四次“一带一路”建设工作座谈会讲话，工作总基调表述为“稳中求进”。D将“以进促稳、先立后破”一并写入，超出了这次讲话的表述。其余三项分别对应共商共建共享原则、互联互通主线和三类联通协调推进机制。","evidence":"要坚持稳中求进、以进促稳、先立后破工作总基调","qids":["政治理论必刷100题#89"]}]}],"sources":[{"id":"81ecb322a280cd46","label":"稳中求进工作总基调","topic":"经济指标与宏观调控","category":"非时政","text":"1.稳中求进工作总基调\n稳中求进工作总基调是我们党治国理政的重要原则，也是做好经济工作的方法论。\n党的十八大以来，习近平总书记围绕坚持稳中求进工作总基调发表一系列重要论述，指出\n“发展是硬道理，稳定也是硬道理，抓发展、抓稳定两手都要硬”，强调“要坚持稳中求\n进、以进促稳、先立后破”。\n习近平总书记强调，“‘稳’的重点要放在稳住经济运行上，确保增长、就业、物价\n不出现大的波动，确保金融不出现区域性系统性风险。‘进’的重点要放在调整经济结构\n和深化改革开放上，确保转变经济发展方式和创新驱动发展取得新成效”。\n“稳”和“进”是辩证统一的关系，“稳”为“进”创造更好的环境和时机，“进”\n为“稳”的动态平衡提供动力支撑。","source":{"doc":"41195a191a57c1c36332","first":21,"last":22,"page":21,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#48":{"paper":"政治理论必刷100题","n":48,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",15],"asrc":["国省考政治理论必刷100题.pdf",62],"card":"0d22e74f10d21a4306d29542","links":[{"id":"k-f21d7fa71f536ad2","role":"直接考查","why":"该意见把稳中求进和促进实体经济与数字经济深度融合作为数字贸易改革创新发展的总体要求。"}]},"政治理论必刷100题#89":{"paper":"政治理论必刷100题","n":89,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",27],"asrc":["国省考政治理论必刷100题.pdf",89],"card":"fc7142002779dd312a7ac770","links":[{"id":"k-f21d7fa71f536ad2","role":"直接考查","why":"须核对座谈会对共建“一带一路”工作总基调的准确表述。"}]}},"terms":{},"references":{"trade":{"name":"中共中央办公厅 国务院办公厅关于数字贸易改革创新发展的意见","url":"https://dltb.mofcom.gov.cn/zcfg/art/2024/art_b3b3c71e681e43cd8f05e6d81c178d9d.html"}},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-f21d7fa71f536ad2":[["政治理论必刷100题#48"],["政治理论必刷100题#89"]]}};
